/* Original, topic-specific schematic diagrams. No external image dependencies. */
function reactivityVisual(s){
  const id=s.id,B='#2d83bd',G='#249b82',O='#d79752',P='#8b68ba',A='#637e98';
  const title=t=>tx(360,24,t,16),foot=t=>tx(360,239,t,11),path=(d,color,width=3,fill='none',extra='')=>`<path d="${d}" fill="${fill}" stroke="${color}" stroke-width="${width}" ${extra}/>`;
  const axes=(x,y,w,h,xlabel,ylabel)=>line(x,y,x+w,y,A,1.5)+line(x,y,x,y-h,A,1.5)+tx(x+w/2,y+24,xlabel,11)+tx(x-6,y-h-12,ylabel,11,A,'start');
  const dot=(x,y,color=B,r=4)=>cir(x,y,r,color,color,1);
  const directed=(x1,y1,x2,y2,color=B)=>{let theta=Math.atan2(y2-y1,x2-x1),len=8;return line(x1,y1,x2,y2,color,2)+path(`M ${x2-len*Math.cos(theta-.5)} ${y2-len*Math.sin(theta-.5)} L ${x2} ${y2} L ${x2-len*Math.cos(theta+.5)} ${y2-len*Math.sin(theta+.5)}`,color,2)};
  let z='';
  if(['R2.2.2','R2.2.4'].includes(id)){
    const points=T=>Array.from({length:251},(_,i)=>{let e=i*2;let f=Math.sqrt(e)*Math.exp(-e/T)/(Math.pow(T,1.5)*Math.sqrt(Math.PI)/2);return[88+e,209-10000*f]});
    const d=pts=>pts.map((p,i)=>(i?'L':'M')+p.join(' ')).join(' '),low=points(45),high=points(85),tail=high.filter(p=>p[0]>=358);
    z=title('Maxwell–Boltzmann distributions: temperature changes the energetic fraction')+axes(88,210,535,151,'Kinetic energy','Number of particles')+path(d(tail)+` L ${tail.at(-1)[0]} 210 L 358 210 Z`,'none',0,'#cdece0')+path(d(low),B)+path(d(high),G)+line(358,210,358,59,O,2,'5 4')+tx(358,50,'Eₐ',13,O)+tx(181,92,'lower T',13,B)+tx(277,133,'higher T',13,G)+tx(505,171,'larger fraction',12,G)+tx(505,189,'above Eₐ',12,G)+foot('Same total particle number → equal curve areas. Heating does not lower Eₐ.');
  }else if(id==='R2.2.5'){
    z=title('Catalysed pathway: lower barrier, unchanged overall enthalpy change')+axes(83,211,555,151,'Reaction progress','Enthalpy')+path('M100 170 C165 170 194 51 282 51 S412 188 618 188',O,4)+path('M100 170 C176 170 208 113 282 113 S414 188 618 188',G,4)+line(122,170,122,52,O,2,'5 4')+line(149,170,149,114,G,2,'4 3')+tx(470,64,'uncatalysed',12,O)+tx(470,90,'catalysed',12,G)+tx(584,176,'products',11)+tx(122,194,'reactants',11)+foot('Both curves share the same reactant and product levels: ΔH is unchanged.');
  }else if(['R2.2.6','R2.2.7'].includes(id)){
    z=title('Two elementary steps: transition states are peaks; intermediate is a minimum')+axes(80,210,555,148,'Reaction progress','Energy')+path('M95 170 C136 170 151 107 198 107 S249 171 306 171 S368 48 421 48 S508 186 620 186',B,4)+dot(198,107,O,5)+dot(306,171,G,5)+dot(421,48,O,5)+tx(198,91,'TS₁',13,O)+tx(421,34,'TS₂',13,O)+tx(304,196,'intermediate',12,G)+line(337,171,337,49,P,2,'4 4')+tx(365,100,'Eₐ,₂',13,P)+foot('For step 2, measure Eₐ upward from the intermediate—not from original reactants.');
  }else if(['R2.2.9','R2.2.10'].includes(id)){
    z=title('Experimental order: compare rate with reactant concentration')+[0,1,2].map((order,i)=>{let x=55+i*229,w=176;let d=order===0?`M${x+9} 135 L${x+w-8} 135`:order===1?`M${x+7} 205 L${x+w-9} 67`:`M${x+7} 205 Q${x+124} 204 ${x+w-9} 67`;return axes(x,207,w,141,'[A]','Rate')+path(d,[O,B,G][i],3)+tx(x+w/2,47,['Zero order','First order','Second order'][i],14,[O,B,G][i])+tx(x+w/2,184,['rate = k','rate = k[A]','rate = k[A]²'][i],11)}).join('')+foot('Determine the exponent experimentally; do not copy overall equation coefficients.');
  }else if(['R2.2.12','R2.2.13'].includes(id)){
    z=title('An Arrhenius plot converts temperature dependence into a straight line')+axes(95,207,525,144,'1 / T (K⁻¹)','ln k')+line(119,69,585,186,B,3)+[0,1,2,3,4].map(i=>dot(137+i*100,74+i*25,B,4)).join('')+line(234,99,455,99,O,1.5,'5 4')+line(455,99,455,154,O,1.5,'5 4')+tx(374,88,'Δ(1/T)',12,O)+tx(486,132,'Δ ln k',12,O)+rect(408,40,245,57,'#fff','#dce7f1',9)+tx(531,63,'gradient = −Eₐ / R',16)+tx(531,84,'intercept = ln A',13,G)+foot('Use natural logarithms, kelvin temperatures, and consistent joule units.');
  }else if(['R2.3.1','R2.3.5'].includes(id)){
    z=title('Dynamic equilibrium: opposing rates become equal, not zero')+axes(82,207,554,145,'Time','Rate')+path('M94 58 C177 106 243 146 334 146 L622 146',B,4)+path('M94 205 C180 177 245 146 334 146 L622 146',G,4)+line(334,61,334,207,O,1.5,'5 4')+tx(241,77,'forward rate',13,B)+tx(185,188,'reverse rate',13,G)+tx(483,128,'equal rates',14)+tx(456,78,'equilibrium reached',12,O)+foot('The molecular reactions continue; concentrations remain constant in a closed system.');
  }else if(id==='R2.3.6'){
    z=title('Equilibrium calculation: track stoichiometric concentration changes')+rect(71,47,577,151,'#fff','#cfdeec',8)+[93,128,163].map(y=>line(71,y,648,y,'#dbe6ef',1)).join('')+[211,354,496].map(x=>line(x,47,x,198,'#dbe6ef',1)).join('')+tx(140,77,'A ⇌ B + C',14,B)+tx(282,77,'[A]',14)+tx(424,77,'[B]',14)+tx(569,77,'[C]',14)+tx(140,116,'Initial',12)+tx(282,116,'0.100',13)+tx(424,116,'0',13)+tx(569,116,'0',13)+tx(140,151,'Change',12)+tx(282,151,'−x',13,O)+tx(424,151,'+x',13,G)+tx(569,151,'+x',13,G)+tx(140,187,'Equilibrium',12)+tx(282,187,'0.100 − x',13)+tx(424,187,'x',13)+tx(569,187,'x',13)+tx(360,222,'K = x² / (0.100 − x) ≈ x² / 0.100 when x is sufficiently small',13)+foot('The approximation must be checked; the guide does not expect quadratic solutions.');
  }else if(['R3.1.4','R3.1.5','R3.1.9'].includes(id)){
    const colors=['#d97c78','#de9275','#e4aa74','#eac477','#dfd788','#aaca8e','#76b998','#5baca9','#629abd','#738bc4','#887bc6','#9e72c1','#b372b4','#bc7ba6','#c18b9e'];
    z=title('At 298 K: pH decreases as hydrogen-ion concentration increases')+colors.map((c,i)=>rect(69+i*39,72,39,36,c,c,0)+tx(88+i*39,131,''+i,12)).join('')+tx(360,58,'pH',15)+tx(88,155,'acidic',13,O)+tx(361,155,'neutral',13,G)+tx(614,155,'basic',13,P)+line(361,69,361,111,'#40725b',3)+directed(599,190,129,190,B)+tx(360,181,'Increasing [H⁺]',13,B)+foot('One pH unit = a factor of ten in [H⁺]. Neutral means [H⁺] = [OH⁻].');
  }else if(['R3.1.8','R3.1.13','R3.1.15'].includes(id)){
    const weak=id!=='R3.1.8';
    z=title(weak?'Weak acid + strong base: buffer region and basic equivalence':'Strong acid + strong base: a sharp stoichiometric equivalence')+axes(84,207,547,154,'Volume of strong base added','pH')+[2,7,12].map(v=>tx(68,211-v*11,''+v,11)).join('')+line(84,130,631,130,'#b6cad8',1,'4 4')+path(weak?'M94 170 C130 158 186 148 270 139 S360 130 374 111 S388 64 401 58 S518 52 622 51':'M94 195 C218 192 334 184 364 164 S375 80 396 65 S507 52 622 51',B,4)+line(381,53,381,207,O,1.5,'4 4')+dot(381,weak?106:130,G,5)+tx(478,108,weak?'equivalence pH > 7':'equivalence pH = 7',12,G)+tx(485,126,'(at 298 K)',11,G)+(weak?dot(231,144,P,4)+tx(224,112,'half-equivalence',11,P)+tx(224,126,'pH = pKₐ',12,P):'')+foot(weak?'The conjugate base remains at equivalence; its hydrolysis produces OH⁻.':'At equivalence: the reacting acid and base amounts match the balanced ratio.');
  }else if(['R3.1.16','R3.1.17'].includes(id)){
    const box=(x,c,t)=>rect(x,67,279,137,'#fff','#dbe7f1',11)+tx(x+139,90,t,14,c);
    z=title('An acidic buffer consumes small additions of either H⁺ or OH⁻')+box(53,B,'A⁻ removes added acid')+box(388,G,'HA removes added base')+atom(117,139,'A⁻','#dceefa',25)+atom(248,139,'H⁺','#f6e1cf',25)+line(144,139,220,139,B,2)+tx(191,173,'A⁻ + H⁺ → HA',14,B)+atom(450,139,'HA','#dff2ea',25)+atom(594,139,'OH⁻','#f1e4f9',25)+line(478,139,565,139,G,2)+tx(528,173,'HA + OH⁻ → A⁻ + H₂O',13,G)+foot('Both conjugate components must be present in appreciable amounts; capacity is finite.');
  }else if(['R3.2.5','R3.2.6','R3.2.12','R3.2.13','R3.2.14'].includes(id)){
    z=title('Zn / Cu voltaic cell: spontaneous electron transfer in an external circuit')+`<path d="M84 105 L84 202 L294 202 L294 105 M424 105 L424 202 L634 202 L634 105" fill="none" stroke="#9bbbd1" stroke-width="3"/><path d="M88 146 L88 198 L290 198 L290 146 M428 146 L428 198 L630 198 L630 146" fill="#dceff7" stroke="none"/><path d="M242 160 L242 114 Q242 89 268 89 L452 89 Q476 89 476 114 L476 160" fill="none" stroke="#b9cbb6" stroke-width="14"/>`+line(143,69,143,171,'#8296a8',13)+line(571,69,571,171,'#c59377',13)+line(143,69,571,69,B,2)+directed(266,57,445,57,B)+tx(356,47,'e⁻ through wire',12,B)+tx(143,97,'Zn',12)+tx(571,97,'Cu',12)+tx(176,225,'anode (−): oxidation',12,O)+tx(548,225,'cathode (+): reduction',12,G)+tx(356,119,'salt bridge',11)+tx(183,184,'Zn²⁺(aq)',12)+tx(541,184,'Cu²⁺(aq)',12)+tx(356,148,'anions ←   → cations',10)+foot('Electrons travel through wire; ions—not electrons—carry charge in the salt bridge.');
  }else if(['R3.2.8','R3.2.15','R3.2.16'].includes(id)){
    const plate=id==='R3.2.16';
    z=title(plate?'Electroplating: the object is the cathode':'Electrolytic cell: the DC source drives non-spontaneous change')+`<path d="M164 104 L164 207 L550 207 L550 104" fill="none" stroke="#94b6cd" stroke-width="3"/><path d="M169 151 L169 201 L545 201 L545 151" fill="#dceef6" stroke="none"/>`+rect(296,44,123,39,'#fff','#a7c2d6',7)+tx(356,70,'DC source',12)+tx(311,66,'+',15,O)+tx(402,66,'−',15,B)+path('M298 64 L229 64 L229 164',A,2)+path('M420 64 L483 64 L483 164',A,2)+line(229,110,229,177,'#bb8f72',14)+line(483,110,483,177,plate?'#8b969d':'#6b879a',14)+tx(229,96,'anode (+)',12,O)+tx(483,96,'cathode (−)',12,B)+directed(325,158,443,158,B)+tx(376,145,plate?'Mⁿ⁺ toward object':'cations →',12,B)+tx(356,188,plate?'Mⁿ⁺ + ne⁻ → M on object':'ions carry charge in electrolyte',12)+foot('Oxidation always occurs at the anode; reduction always occurs at the cathode.');
  }else if(['R3.4.9','R3.4.10'].includes(id)){
    z=title('Substitution pathways: one barrier for SN2; two barriers for SN1')+axes(57,202,267,136,'Reaction progress','Energy')+axes(403,202,267,136,'Reaction progress','Energy')+path('M68 170 C125 170 138 70 188 70 S250 179 314 179',B,3)+path('M414 169 C446 169 453 76 484 76 S521 160 548 160 S581 112 607 112 S639 180 660 180',G,3)+tx(186,52,'SN2 · primary model',14,B)+tx(537,52,'SN1 · tertiary model',14,G)+dot(548,160,O,4)+tx(539,184,'carbocation',10,O)+tx(188,151,'one transition state',11,B)+foot('SN2: concerted backside attack / inversion. SN1: carbocation intermediate, then attack.');
  }else{return null;}
  return svg(z);
}
